/**
 * The brand mark, inlined.
 *
 * The social card is drawn by Satori, which needs the actual bytes at render
 * time — it cannot reach into `public/`, and a file path that survives local
 * development but not the serverless build is the classic way an OG image goes
 * blank in production without anyone noticing. So the mark travels with the
 * code. It is small on purpose: 128px, which is four times the size it is ever
 * drawn at.
 *
 * The full-resolution copy lives at `public/brand/mark.png` and is what CSS and
 * the favicon use.
 */
export const BRAND_MARK_DATA_URI =
  "data:image/png;base64,";
